"""Comprehensive tests for the A* pathfinding algorithm."""

import math
import pytest

from astar import (
    astar,
    chebyshev_distance,
    euclidean_distance,
    manhattan_distance,
    zero_heuristic,
)


# ── helpers ────────────────────────────────────────────────────────────


def _grid(width: int, height: int, walls=None):
    """Build a 4-connected grid graph with optional wall edges."""
    walls = walls or set()
    g = {}
    for x in range(width):
        for y in range(height):
            nbrs = []
            for dx, dy in [(1, 0), (0, 1), (-1, 0), (0, -1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < width and 0 <= ny < height:
                    edge = ((x, y), (nx, ny))
                    if edge not in walls:
                        nbrs.append(((nx, ny), 1))
            g[(x, y)] = nbrs
    return g


# ── basic correctness ─────────────────────────────────────────────────


class TestBasicPathfinding:
    def test_simple_linear_path(self):
        g = {"A": [("B", 1)], "B": [("C", 1)], "C": []}
        path, cost = astar(g, "A", "C", zero_heuristic)
        assert path == ["A", "B", "C"]
        assert cost == 2

    def test_diamond_graph_picks_shortest(self):
        #     B
        #    / \
        # A-1   2-D
        #    \ /
        #     C
        g = {
            "A": [("B", 1), ("C", 3)],
            "B": [("D", 2)],
            "C": [("D", 1)],
            "D": [],
        }
        path, cost = astar(g, "A", "D", zero_heuristic)
        assert path == ["A", "B", "D"]
        assert cost == 3

    def test_diamond_graph_shorter_lower_path(self):
        g = {
            "A": [("B", 3), ("C", 1)],
            "B": [("D", 1)],
            "C": [("D", 2)],
            "D": [],
        }
        path, cost = astar(g, "A", "D", zero_heuristic)
        assert path == ["A", "C", "D"]
        assert cost == 3

    def test_graph_from_docstring(self):
        g = {
            "A": [("B", 1), ("C", 4)],
            "B": [("C", 3), ("D", 2)],
            "C": [("D", 1)],
            "D": [],
        }
        path, cost = astar(g, "A", "D", zero_heuristic)
        assert path == ["A", "B", "D"]
        assert cost == 3


# ── heuristic tests ───────────────────────────────────────────────────


class TestHeuristics:
    def test_zero_heuristic_equals_dijkstra(self):
        g = {
            "A": [("B", 2), ("C", 5)],
            "B": [("C", 1)],
            "C": [],
        }
        path, cost = astar(g, "A", "C", zero_heuristic)
        assert path == ["A", "B", "C"]
        assert cost == 3

    def test_manhattan_distance(self):
        h = manhattan_distance((3, 4))
        assert h((0, 0)) == 7
        assert h((3, 4)) == 0
        assert h((1, 2)) == 4

    def test_euclidean_distance(self):
        h = euclidean_distance((3, 0))
        assert h((0, 0)) == pytest.approx(3.0)
        assert h((3, 0)) == pytest.approx(0.0)
        assert h((0, 4)) == pytest.approx(5.0)

    def test_chebyshev_distance(self):
        h = chebyshev_distance((3, 5))
        assert h((0, 0)) == 5
        assert h((3, 5)) == 0
        assert h((1, 2)) == 3

    def test_heuristic_changes_exploration_order_not_result(self):
        """Both zero and Manhattan heuristics find the same optimal cost."""
        g = _grid(5, 5)
        goal = (4, 4)
        _, cost_zero = astar(g, (0, 0), goal, zero_heuristic)
        _, cost_manh = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert cost_zero == cost_manh == 8


# ── grid / maze tests ─────────────────────────────────────────────────


class TestGridPathfinding:
    def test_open_grid(self):
        g = _grid(4, 4)
        goal = (3, 3)
        path, cost = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert cost == 6  # Manhattan distance on open grid
        assert len(path) == 7

    def test_grid_with_wall_forces_detour(self):
        # Wall blocks the direct horizontal path along row 1.
        walls = {((1, 0), (1, 1)), ((1, 1), (1, 0))}
        g = _grid(3, 3, walls)
        goal = (2, 0)
        path, cost = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert cost == 4  # Must detour

    def test_grid_completely_walled_off(self):
        # Surround (1,1) with walls on all four sides.
        walls = {
            ((1, 0), (1, 1)), ((1, 1), (1, 0)),
            ((0, 1), (1, 1)), ((1, 1), (0, 1)),
            ((2, 1), (1, 1)), ((1, 1), (2, 1)),
            ((1, 2), (1, 1)), ((1, 1), (1, 2)),
        }
        g = _grid(3, 3, walls)
        _, cost = astar(g, (0, 0), (1, 1), manhattan_distance((1, 1)))
        assert cost == float("inf")

    def test_single_cell_grid(self):
        g = _grid(1, 1)
        path, cost = astar(g, (0, 0), (0, 0), zero_heuristic)
        assert path == [(0, 0)]
        assert cost == 0

    def test_2x2_grid(self):
        g = _grid(2, 2)
        goal = (1, 1)
        path, cost = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert cost == 2

    def test_large_grid_performance(self):
        """A* on a 100x100 grid should complete quickly."""
        g = _grid(100, 100)
        goal = (99, 99)
        path, cost = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert cost == 198


# ── edge cases ─────────────────────────────────────────────────────────


class TestEdgeCases:
    def test_source_equals_target(self):
        g = {"A": [("B", 1)], "B": []}
        path, cost = astar(g, "A", "A", zero_heuristic)
        assert path == ["A"]
        assert cost == 0

    def test_disconnected_target(self):
        g = {"A": [], "B": []}
        path, cost = astar(g, "A", "B", zero_heuristic)
        assert path == []
        assert cost == float("inf")

    def test_target_behind_dead_end(self):
        g = {
            "A": [("B", 1)],
            "B": [("C", 1)],
            "C": [],  # C has no outgoing edges
            "D": [],
        }
        path, cost = astar(g, "A", "D", zero_heuristic)
        assert path == []
        assert cost == float("inf")

    def test_parallel_edges_keeps_lightest(self):
        g = {"A": [("B", 5), ("B", 2)], "B": []}
        path, cost = astar(g, "A", "B", zero_heuristic)
        assert cost == 2

    def test_self_loop(self):
        g = {"A": [("A", 1), ("B", 1)], "B": []}
        path, cost = astar(g, "A", "B", zero_heuristic)
        assert path == ["A", "B"]
        assert cost == 1

    def test_cycle_in_graph(self):
        g = {
            "A": [("B", 1)],
            "B": [("C", 1)],
            "C": [("A", 1), ("D", 1)],
            "D": [],
        }
        path, cost = astar(g, "A", "D", zero_heuristic)
        assert path == ["A", "B", "C", "D"]
        assert cost == 3

    def test_float_weights(self):
        g = {"A": [("B", 0.5), ("C", 1.5)], "B": [("C", 0.5)], "C": []}
        path, cost = astar(g, "A", "C", zero_heuristic)
        assert path == ["A", "B", "C"]
        assert cost == pytest.approx(1.0)

    def test_large_weight(self):
        w = 10**12
        g = {"A": [("B", w)], "B": []}
        _, cost = astar(g, "A", "B", zero_heuristic)
        assert cost == w


# ── error handling ─────────────────────────────────────────────────────


class TestErrors:
    def test_source_not_in_graph(self):
        g = {"A": []}
        with pytest.raises(KeyError, match="source"):
            astar(g, "Z", "A", zero_heuristic)

    def test_target_not_in_graph(self):
        g = {"A": []}
        with pytest.raises(KeyError, match="target"):
            astar(g, "A", "Z", zero_heuristic)

    def test_empty_graph(self):
        with pytest.raises(KeyError):
            astar({}, "A", "B", zero_heuristic)

    def test_negative_weight_raises(self):
        g = {"A": [("B", -1)], "B": []}
        with pytest.raises(ValueError, match="negative"):
            astar(g, "A", "B", zero_heuristic)

    def test_negative_weight_on_non_source_edge(self):
        g = {
            "A": [("B", 1)],
            "B": [("C", -5)],
            "C": [],
        }
        with pytest.raises(ValueError, match="negative"):
            astar(g, "A", "C", zero_heuristic)


# ── heuristic correctness (admissibility) ─────────────────────────────


class TestHeuristicAdmissibility:
    def test_inadmissible_heuristic_still_finds_path(self):
        """An inadmissible heuristic may not find the optimal path but won't crash."""
        g = {
            "A": [("B", 1), ("C", 10)],
            "B": [("D", 1)],
            "C": [("D", 1)],
            "D": [],
        }

        def bad_heuristic(_node):
            return 100  # massively overestimates

        path, cost = astar(g, "A", "D", bad_heuristic)
        # Should still find *a* path, though not guaranteed optimal
        assert len(path) > 0
        assert path[0] == "A"
        assert path[-1] == "D"

    def test_manhattan_is_admissible_on_grid(self):
        """Manhattan distance never overestimates on a 4-connected grid."""
        g = _grid(6, 6)
        goal = (5, 5)
        _, cost_optimal = astar(g, (0, 0), goal, zero_heuristic)
        _, cost_manh = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert cost_manh == cost_optimal

    def test_euclidean_is_admissible_on_grid(self):
        g = _grid(6, 6)
        goal = (5, 5)
        _, cost_optimal = astar(g, (0, 0), goal, zero_heuristic)
        _, cost_euc = astar(g, (0, 0), goal, euclidean_distance(goal))
        assert cost_euc == cost_optimal


# ── weighted grid (non-uniform costs) ─────────────────────────────────


class TestWeightedGraphs:
    def test_terrain_costs(self):
        """Higher-cost 'rough terrain' edges should be avoided if a cheaper path exists."""
        g = {
            "Start": [("A", 1), ("B", 10)],
            "A": [("Goal", 1)],
            "B": [("Goal", 1)],
            "Goal": [],
        }
        path, cost = astar(g, "Start", "Goal", zero_heuristic)
        assert path == ["Start", "A", "Goal"]
        assert cost == 2

    def test_all_paths_expensive(self):
        g = {
            "A": [("B", 100), ("C", 200)],
            "B": [("D", 100)],
            "C": [("D", 50)],
            "D": [],
        }
        path, cost = astar(g, "A", "D", zero_heuristic)
        assert path == ["A", "B", "D"]
        assert cost == 200


# ── string / tuple / int vertex types ─────────────────────────────────


class TestVertexTypes:
    def test_integer_vertices(self):
        g = {0: [(1, 2), (2, 5)], 1: [(2, 1)], 2: []}
        path, cost = astar(g, 0, 2, zero_heuristic)
        assert path == [0, 1, 2]
        assert cost == 3

    def test_tuple_vertices(self):
        g = {
            (0, 0): [((1, 0), 1)],
            (1, 0): [((1, 1), 1)],
            (1, 1): [],
        }
        path, cost = astar(g, (0, 0), (1, 1), zero_heuristic)
        assert path == [(0, 0), (1, 0), (1, 1)]
        assert cost == 2

    def test_mixed_hashable_types(self):
        g = {
            0: [("a", 1)],
            "a": [(1.5, 2)],
            1.5: [],
        }
        path, cost = astar(g, 0, 1.5, zero_heuristic)
        assert path == [0, "a", 1.5]
        assert cost == 3


# ── path reconstruction ───────────────────────────────────────────────


class TestPathReconstruction:
    def test_path_starts_and_ends_correctly(self):
        g = _grid(5, 5)
        goal = (4, 4)
        path, _ = astar(g, (0, 0), goal, manhattan_distance(goal))
        assert path[0] == (0, 0)
        assert path[-1] == (4, 4)

    def test_path_is_contiguous(self):
        g = _grid(5, 5)
        goal = (4, 4)
        path, _ = astar(g, (0, 0), goal, manhattan_distance(goal))
        for i in range(len(path) - 1):
            neighbors = [v for v, _ in g[path[i]]]
            assert path[i + 1] in neighbors

    def test_path_cost_matches_sum_of_edges(self):
        g = _grid(5, 5)
        goal = (4, 4)
        path, cost = astar(g, (0, 0), goal, manhattan_distance(goal))
        total = 0
        for i in range(len(path) - 1):
            edge_weights = {v: w for v, w in g[path[i]]}
            total += edge_weights[path[i + 1]]
        assert total == cost
